// 集計期間の設定（必要に応じて編集）
const i = $input.first().json;
return [{ json: {
  experiment_id: i.experiment_id ?? 'exp-001',
  period_start: i.period_start ?? '2026-08-01',
  period_end: i.period_end ?? '2026-08-08'
} }];

// Gumroad応答をパース。失敗時は欠損をerrorで明示（捏造しない）。
const g = $input.first().json;
let gumroad_sales = null, gumroad_error = null;
if (g && g.error) { gumroad_error = 'gumroad_api_error'; }
else if (g && g.products) { gumroad_sales = g.products.reduce((s,p)=> s + (p.sales_count || 0), 0) || 0; }
else { gumroad_error = 'gumroad_parse_failed'; }
const cfg = $('Config').first().json;
return [{ json: { ...cfg, gumroad_sales, gumroad_error } }];

// ▼▼ 手入力メトリクス（自動取得できない媒体）。週1でここの数字を最新に更新してください ▼▼
// note/Brainは公式APIが無いため、各管理画面の数字をここに転記します。
const prev = $input.first().json;
const manual = {
  note_sales: 0,          // note 有料記事の販売件数
  note_views: 0,          // note 閲覧数
  brain_sales: 0,         // Brain 販売件数
  threads_impressions: 0, // Threads 表示数（将来API化予定）
  threads_clicks: 0,      // Threads クリック/プロフ遷移
  asp_conversions: 0,     // WPアフィリ成果件数（A8/もしも）
  cost_anthropic: 0,      // API費用（円）
  cost_browser: 0,        // 自動化・その他費用（円）
  owner_hours: 0          // オーナー稼働時間（h）
};
return [{ json: { ...prev, ...manual } }];

// 売上・費用・KPIを集計。欠損はそのまま（捏造しない）。
const d = $input.first().json;
const total_revenue = (d.gumroad_sales||0) + (d.note_sales||0) + (d.brain_sales||0);
const total_cost = (d.cost_anthropic||0) + (d.cost_browser||0);
const gross_profit = total_revenue - total_cost;
const kpi = d.owner_hours > 0 ? +(gross_profit / d.owner_hours).toFixed(1) : null;
return [{ json: {
  experiment_id: d.experiment_id,
  period: d.period_start + ' 〜 ' + d.period_end,
  metrics: {
    gumroad_sales: d.gumroad_sales,
    note_sales: d.note_sales,
    brain_sales: d.brain_sales,
    note_views: d.note_views,
    threads_impressions: d.threads_impressions,
    threads_clicks: d.threads_clicks,
    asp_conversions: d.asp_conversions,
    total_revenue, total_cost, gross_profit,
    owner_hours: d.owner_hours,
    kpi_profit_per_hour: kpi
  },
  errors: { gumroad: d.gumroad_error },
  state: 'READY_FOR_DECISION'
} }];

// LINE等に送る通知テキストを整形。
const d = $input.first().json;
const m = d.metrics;
const lines = [
  '【RIO 日次メトリクス】' + d.period,
  '売上合計: ' + m.total_revenue + '円',
  '  Gumroad ' + (m.gumroad_sales ?? '-') + ' / note ' + m.note_sales + ' / Brain ' + m.brain_sales,
  '費用: ' + m.total_cost + '円 / 粗利: ' + m.gross_profit + '円',
  'KPI(粗利/時): ' + (m.kpi_profit_per_hour ?? 'N/A'),
  'Gumroad取得: ' + (d.errors.gumroad ? 'エラー(' + d.errors.gumroad + ')' : 'OK')
];
return [{ json: { ...d, notification_text: lines.join('\n') } }];
